  "title": "functions.alpha_vector.PlaceholderScalarFunctionTaskExpression",
  "type": "object",
  "properties": {
    "depth": {
      "type": "integer",
      "format": "uint64",
      "minimum": 0
    },
    "min_branch_width": {
      "type": "integer",
      "format": "uint64",
      "minimum": 0
    },
    "max_branch_width": {
      "type": "integer",
      "format": "uint64",
      "minimum": 0
    },
    "min_leaf_width": {
      "type": "integer",
      "format": "uint64",
      "minimum": 0
    },
    "max_leaf_width": {
      "type": "integer",
      "format": "uint64",
      "minimum": 0
    },
    "name": {
      "type": "string"
    },
    "spec": {
      "type": "string"
    },
    "input_schema": {
      "$ref": "functions.expression.ObjectInputSchema"
    },
    "skip": {
      "anyOf": [
        {
          "$ref": "functions.expression.Expression"
        },
        {
          "type": "null"
        }
      ]
    },
    "input": {
      "$ref": "functions.expression.Expression"
    }
  },
  "required": [
    "depth",
    "min_branch_width",
    "max_branch_width",
    "min_leaf_width",
    "max_leaf_width",
    "name",
    "spec",
    "input_schema",
    "input"
  ]
}

